CREATE DATABASE IF NOT EXISTS enterprise_ai_worker
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE enterprise_ai_worker;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
CREATE TABLE `roles` (
  `name` VARCHAR(40),
  `min_experience_years` INT,
  `required_skills` JSON,
  `min_performance` INT,
  `min_skill_test` INT,
  `min_participation` INT,
  `min_shift_completion` DECIMAL(4,3),
  `min_production_ratio` DECIMAL(4,3),
  `exam_required` TINYINT(1),
  `interview_required` TINYINT(1),
  PRIMARY KEY (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `customers` (
  `id` VARCHAR(16),
  `name` VARCHAR(80),
  `status` VARCHAR(16),
  `membership_months` INT,
  `loyalty_score` INT,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `orders` (
  `id` VARCHAR(16),
  `customer_id` VARCHAR(16),
  `amount` INT,
  `return_window_days` INT,
  `days_since_delivery` INT,
  `item_category` VARCHAR(32),
  `payment_status` VARCHAR(16),
  `refund_status` VARCHAR(16),
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_orders_customer_id` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `discounts` (
  `id` VARCHAR(16),
  `customer_id` VARCHAR(16),
  `code` VARCHAR(24),
  `percent` INT,
  `cap` INT,
  `min_order_value` INT,
  `status` VARCHAR(16),
  `valid_until` DATE,
  `source` VARCHAR(32),
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_discounts_customer_id` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `refunds` (
  `id` VARCHAR(20),
  `order_id` VARCHAR(16),
  `customer_id` VARCHAR(16),
  `amount` INT,
  `status` VARCHAR(20),
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_refunds_order_id` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`),
  CONSTRAINT `fk_refunds_customer_id` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `tickets` (
  `id` VARCHAR(16),
  `customer_id` VARCHAR(16),
  `order_id` VARCHAR(16),
  `category` VARCHAR(20),
  `subject` VARCHAR(120),
  `description` VARCHAR(400),
  `priority` VARCHAR(12),
  `status` VARCHAR(28),
  `auto_solved` TINYINT(1),
  `resolution` VARCHAR(400),
  `created_at` DATETIME,
  `updated_at` DATETIME,
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_tickets_customer_id` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`),
  CONSTRAINT `fk_tickets_order_id` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `employees` (
  `id` VARCHAR(16),
  `name` VARCHAR(80),
  `role` VARCHAR(40),
  `base_pay` INT,
  `active` TINYINT(1),
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_employees_role` FOREIGN KEY (`role`) REFERENCES `roles` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `employee_performance` (
  `employee_id` VARCHAR(16),
  `performance` INT,
  `participation` INT,
  `shifts_completed` INT,
  `shifts_scheduled` INT,
  `production` INT,
  `production_target` INT,
  `skill_test` INT,
  `attendance` INT,
  `experience_years` DECIMAL(4,1),
  `skills` JSON,
  PRIMARY KEY (`employee_id`),
  CONSTRAINT `fk_employee_performance_employee_id` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `payroll` (
  `employee_id` VARCHAR(16),
  `pay_period` VARCHAR(8),
  `status` VARCHAR(16),
  `net_pay` INT,
  `pay_date` DATE,
  PRIMARY KEY (`employee_id`),
  CONSTRAINT `fk_payroll_employee_id` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `bonuses` (
  `id` VARCHAR(16),
  `employee_id` VARCHAR(16),
  `score` DECIMAL(6,2),
  `bonus` DECIMAL(12,2),
  `status` VARCHAR(20),
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_bonuses_employee_id` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `promotion_assessments` (
  `id` VARCHAR(16),
  `employee_id` VARCHAR(16),
  `role` VARCHAR(40),
  `exam_authorized` TINYINT(1),
  `interview_authorized` TINYINT(1),
  `final_promotion` TINYINT(1),
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_promotion_assessments_employee_id` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`),
  CONSTRAINT `fk_promotion_assessments_role` FOREIGN KEY (`role`) REFERENCES `roles` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `vendors` (
  `id` VARCHAR(16),
  `name` VARCHAR(80),
  `payment_status` VARCHAR(16),
  `invoice_id` VARCHAR(24),
  `invoice_total` INT,
  `invoice_file` VARCHAR(80),
  `email` VARCHAR(120),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `vendor_emails` (
  `vendor_id` VARCHAR(16),
  `email` VARCHAR(120),
  PRIMARY KEY (`vendor_id`),
  CONSTRAINT `fk_vendor_emails_vendor_id` FOREIGN KEY (`vendor_id`) REFERENCES `vendors` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `inventory` (
  `sku` VARCHAR(24),
  `product` VARCHAR(80),
  `stock` INT,
  `reorder_point` INT,
  `reorder_qty` INT,
  `vendor_id` VARCHAR(16),
  `unit_cost` INT,
  PRIMARY KEY (`sku`),
  CONSTRAINT `fk_inventory_vendor_id` FOREIGN KEY (`vendor_id`) REFERENCES `vendors` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `vendor_email_log` (
  `id` VARCHAR(16),
  `to_email` VARCHAR(120),
  `vendor_id` VARCHAR(16),
  `subject` VARCHAR(120),
  `body` VARCHAR(400),
  `status` VARCHAR(16),
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_vendor_email_log_vendor_id` FOREIGN KEY (`vendor_id`) REFERENCES `vendors` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `json_store` (
  `name` VARCHAR(255) NOT NULL,
  `payload` JSON NOT NULL,
  `updated_at` DATETIME NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

















